#[derive(Debug)]
enum InvocationError {
    InvalidParams(String),
    ResourceNotFound {
        uri: String,
    },
    Internal(String),
    TransportLimit {
        required_bytes: usize,
        limit_bytes: usize,
        omitted_bytes: usize,
    },
}

impl InvocationError {
    fn protocol_error(self) -> ErrorData {
        match self {
            Self::InvalidParams(message) => ErrorData::invalid_params(message, None),
            Self::ResourceNotFound { uri } => ErrorData::invalid_params(
                format!("Unknown resource: {uri}"),
                Some(json!({ "uri": uri })),
            ),
            Self::Internal(message) => ErrorData::internal_error(message, None),
            Self::TransportLimit {
                required_bytes,
                limit_bytes,
                omitted_bytes,
            } => ErrorData::internal_error(
                "MCP transport bound would truncate a semantic result".to_owned(),
                Some(json!({
                    "schema": MCP_TRANSPORT_TRUNCATION_SCHEMA,
                    "truncated": true,
                    "requiredBytes": required_bytes,
                    "limitBytes": limit_bytes,
                    "omittedBytes": omitted_bytes,
                })),
            ),
        }
    }
}

impl std::fmt::Display for InvocationError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::InvalidParams(message) | Self::Internal(message) => formatter.write_str(message),
            Self::ResourceNotFound { uri } => write!(formatter, "Unknown resource: {uri}"),
            Self::TransportLimit {
                required_bytes,
                limit_bytes,
                omitted_bytes,
            } => write!(
                formatter,
                "MCP response requires {required_bytes} bytes; transport limit is {limit_bytes} bytes ({omitted_bytes} omitted)"
            ),
        }
    }
}

impl From<String> for InvocationError {
    fn from(message: String) -> Self {
        Self::InvalidParams(message)
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct FileKey {
    modified: Option<SystemTime>,
    size: u64,
}

#[derive(Debug)]
struct GraphContext {
    path: PathBuf,
    graph: Graph,
    overlay: HashMap<String, Map<String, Value>>,
    communities: BTreeMap<usize, Vec<NodeIndex>>,
    typed_query_supported: bool,
    typed_document: Option<CodeGraphDocument>,
    typed_graph_identity: Option<String>,
}

impl GraphContext {
    fn load(path: &Path) -> Result<Self, String> {
        let loaded = LoadedGraph::load_directed(path).map_err(|error| error.to_string())?;
        let (typed_document, typed_graph_identity) =
            match CodeGraphDocument::load_with_artifact_digest(path) {
                Ok((document, identity)) => (Some(document), Some(identity)),
                Err(_) => (None, None),
            };
        let typed_query_supported = typed_document.is_some();
        let mut communities = BTreeMap::<usize, Vec<NodeIndex>>::new();
        for (index, node) in loaded.graph.nodes() {
            if let Some(community) = node
                .unsigned("community")
                .or_else(|| node.string("community").parse().ok())
                .and_then(|value| usize::try_from(value).ok())
            {
                communities.entry(community).or_default().push(index);
            }
        }
        Ok(Self {
            path: path.to_path_buf(),
            graph: loaded.graph,
            overlay: loaded.overlay,
            communities,
            typed_query_supported,
            typed_document,
            typed_graph_identity,
        })
    }

    fn document(&self) -> Result<GraphDocument, String> {
        GraphDocument::load(&self.path).map_err(|error| error.to_string())
    }

    fn community_ids(&self) -> Communities {
        self.communities
            .iter()
            .map(|(community, nodes)| {
                (
                    *community,
                    nodes
                        .iter()
                        .map(|index| self.graph.node(*index).id.clone())
                        .collect(),
                )
            })
            .collect()
    }
}

#[derive(Debug)]
struct CacheEntry {
    key: FileKey,
    context: Arc<GraphContext>,
}

struct StoreInner {
    default_graph: PathBuf,
    engine: compass_query::EngineSelection,
    cache: Mutex<HashMap<PathBuf, CacheEntry>>,
    typed_queries: compass_query::QueryEngineCache,
    #[cfg(any(
        feature = "surreal-surrealkv",
        feature = "surreal-rocksdb",
        feature = "surreal-remote"
    ))]
    surreal_queries: compass_query::SurrealQueryEngineCache,
}

/// Hot-reloading, multi-project graph store shared by every MCP session.
#[derive(Clone)]
pub struct GraphStore {
    inner: Arc<StoreInner>,
}

impl std::fmt::Debug for GraphStore {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("GraphStore")
            .field("default_graph", &self.inner.default_graph)
            .field("typed_query_engines", &self.inner.typed_queries.len())
            .finish()
    }
}

impl GraphStore {
    #[must_use]
    pub fn new(default_graph: impl Into<PathBuf>) -> Self {
        Self::new_with_engine(default_graph, compass_query::EngineSelection::Default)
    }

    #[must_use]
    pub fn new_with_engine(
        default_graph: impl Into<PathBuf>,
        engine: compass_query::EngineSelection,
    ) -> Self {
        Self {
            inner: Arc::new(StoreInner {
                default_graph: default_graph.into(),
                engine,
                cache: Mutex::new(HashMap::new()),
                typed_queries: compass_query::QueryEngineCache::default(),
                #[cfg(any(
                    feature = "surreal-surrealkv",
                    feature = "surreal-rocksdb",
                    feature = "surreal-remote"
                ))]
                surreal_queries: compass_query::SurrealQueryEngineCache::default(),
            }),
        }
    }

    fn selects_surreal(&self, graph_path: &Path) -> Result<bool, InvocationError> {
        let published = compass_query::has_published_surreal_compatible(graph_path);
        match self.inner.engine {
            compass_query::EngineSelection::Surreal => {
                if !cfg!(any(
                    feature = "surreal-surrealkv",
                    feature = "surreal-rocksdb",
                    feature = "surreal-remote"
                )) {
                    return Err(InvocationError::InvalidParams(
                        "this Compass MCP server was built without a SurrealDB engine".to_owned(),
                    ));
                }
                if !published {
                    return Err(InvocationError::InvalidParams(format!(
                        "explicit Surreal MCP engine requires {}",
                        graph_path
                            .parent()
                            .unwrap_or_else(|| Path::new("."))
                            .join("surreal.ref")
                            .display()
                    )));
                }
                Ok(true)
            }
            compass_query::EngineSelection::Default => Ok(published
                && cfg!(any(
                    feature = "surreal-surrealkv",
                    feature = "surreal-rocksdb",
                    feature = "surreal-remote"
                ))),
            compass_query::EngineSelection::Json | compass_query::EngineSelection::Store => {
                Ok(false)
            }
        }
    }

    fn selects_store(&self, graph_path: &Path) -> bool {
        let usable_surreal = cfg!(any(
            feature = "surreal-surrealkv",
            feature = "surreal-rocksdb",
            feature = "surreal-remote"
        )) && compass_query::has_published_surreal_compatible(graph_path);
        self.inner.engine == compass_query::EngineSelection::Store
            || (self.inner.engine == compass_query::EngineSelection::Default
                && !usable_surreal
                && compass_query::has_published_store(graph_path))
    }

    fn resolve(&self, project_path: Option<&str>) -> Result<PathBuf, String> {
        project_path.map_or_else(
            || {
                compass_files::BuildGuard::resolve_requested_artifact(&self.inner.default_graph)
                    .map_err(|error| error.to_string())
            },
            |project| {
                let output = std::env::var_os("COMPASS_OUT")
                    .map(PathBuf::from)
                    .unwrap_or_else(|| PathBuf::from("compass-out"));
                let output = Path::new(project).join(output);
                compass_files::BuildGuard::resolve_requested_artifact(&output.join("graph.json"))
                    .map_err(|error| error.to_string())
            },
        )
    }

    fn source_root(&self, project_path: Option<&str>) -> Result<PathBuf, String> {
        project_path.map_or_else(
            || std::env::current_dir().map_err(|error| error.to_string()),
            |project| Ok(PathBuf::from(project)),
        )
    }

    fn load(&self, project_path: Option<&str>) -> Result<Arc<GraphContext>, String> {
        let path = self.resolve(project_path)?;
        let metadata =
            fs::metadata(&path).map_err(|_| format!("graph.json not found: {}", path.display()))?;
        let key = FileKey {
            modified: metadata.modified().ok(),
            size: metadata.len(),
        };
        if let Some(context) = self
            .inner
            .cache
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .get(&path)
            .filter(|entry| entry.key == key)
            .map(|entry| Arc::clone(&entry.context))
        {
            return Ok(context);
        }
        let context = Arc::new(GraphContext::load(&path)?);
        self.inner
            .cache
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .insert(
                path,
                CacheEntry {
                    key,
                    context: Arc::clone(&context),
                },
            );
        Ok(context)
    }
}

/// One MCP service instance. Clones share the hot-reload cache.
#[derive(Clone, Debug)]
pub struct CompassMcp {
    store: GraphStore,
    protocol_profile: ProtocolProfile,
    agent_graph: Option<Arc<AgentGraphMcpConfig>>,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ProtocolProfile {
    Stdio2026,
    Http2026,
}

/// Trusted server-side scope for Agent Graph tools. None of these values are accepted from a
/// tool request, and the project allowlist is canonicalized before the server starts.
#[derive(Clone, Debug)]
pub struct AgentGraphMcpConfig {
    pub writes_enabled: bool,
    pub masks_enabled: bool,
    pub principal: PrincipalId,
    pub allowed_projects: BTreeSet<PathBuf>,
    pub non_git_state_root: Option<PathBuf>,
}

impl AgentGraphMcpConfig {
    pub fn validate(mut self) -> Result<Self, String> {
        if self.allowed_projects.is_empty() {
            return Err(
                "agent graph MCP configuration requires a non-empty project allowlist".to_owned(),
            );
        }
        let mut canonical = BTreeSet::new();
        for root in self.allowed_projects {
            let root = root
                .canonicalize()
                .map_err(|error| format!("cannot canonicalize agent graph project: {error}"))?;
            if !root.is_dir() {
                return Err("agent graph project allowlist entries must be directories".to_owned());
            }
            canonical.insert(root);
        }
        self.allowed_projects = canonical;
        if self.non_git_state_root.is_some() && self.allowed_projects.len() != 1 {
            return Err(
                "one explicit non-Git state root may be scoped to exactly one project".to_owned(),
            );
        }
        if self.masks_enabled && !self.writes_enabled {
            return Err("agent graph masks require writes to be enabled".to_owned());
        }
        Ok(self)
    }
}

impl CompassMcp {
    #[must_use]
    pub fn new(graph_path: impl Into<PathBuf>) -> Self {
        Self::new_with_engine(graph_path, compass_query::EngineSelection::Default)
    }

    #[must_use]
    pub fn new_with_engine(
        graph_path: impl Into<PathBuf>,
        engine: compass_query::EngineSelection,
    ) -> Self {
        Self {
            store: GraphStore::new_with_engine(graph_path, engine),
            protocol_profile: ProtocolProfile::Stdio2026,
            agent_graph: None,
        }
    }

    pub(crate) fn new_http_with_engine(
        graph_path: impl Into<PathBuf>,
        engine: compass_query::EngineSelection,
    ) -> Self {
        Self {
            store: GraphStore::new_with_engine(graph_path, engine),
            protocol_profile: ProtocolProfile::Http2026,
            agent_graph: None,
        }
    }

    pub fn with_agent_graph(mut self, config: AgentGraphMcpConfig) -> Result<Self, String> {
        self.agent_graph = Some(Arc::new(config.validate()?));
        Ok(self)
    }

    #[must_use]
    pub fn tools() -> Vec<Tool> {
        tool_specs()
    }

    #[must_use]
    pub fn configured_tools(&self) -> Vec<Tool> {
        configured_tool_specs(self.agent_graph.as_deref())
    }

    #[must_use]
    pub fn resources() -> Vec<Resource> {
        resource_specs()
    }

    /// Invoke a graph tool without a transport, primarily for compatibility tests.
    #[must_use]
    pub fn invoke(&self, name: &str, mut arguments: Map<String, Value>) -> String {
        let runtime = tokio::runtime::Builder::new_multi_thread()
            .worker_threads(2)
            .enable_all()
            .build();
        let result = runtime
            .map_err(|error| InvocationError::Internal(error.to_string()))
            .and_then(|runtime| runtime.block_on(self.invoke_result(name, &mut arguments)));
        result
            .map(|result| {
                result
                    .structured_content
                    .map_or(result.text, |value| value.to_string())
            })
            .unwrap_or_else(|error| format!("Error executing {name}: {error}"))
    }

    /// Read a compass resource without a transport.
    pub fn read(&self, uri: &str) -> Result<String, String> {
        self.read_result(uri).map_err(|error| error.to_string())
    }

    fn read_result(&self, uri: &str) -> Result<String, InvocationError> {
        let context = self.store.load(None).map_err(InvocationError::Internal)?;
        let text = read_resource_text(uri, &context)?;
        if text.len() > MAX_MCP_RESOURCE_BYTES {
            return Err(InvocationError::TransportLimit {
                required_bytes: text.len(),
                limit_bytes: MAX_MCP_RESOURCE_BYTES,
                omitted_bytes: text.len().saturating_sub(MAX_MCP_RESOURCE_BYTES),
            });
        }
        Ok(text)
    }
}

impl ServerHandler for CompassMcp {
    /// `initialize` for every revision that still defines it.
    ///
    /// `2026-07-28` replaced `initialize` with `server/discover` (SEP-2575), so a client naming it
    /// is refused here exactly as the HTTP gate refuses it. That keeps stdio and HTTP consistent.
    /// Older revisions use rmcp's negotiation helper, which keeps initialize on legacy versions.
    fn initialize(
        &self,
        request: InitializeRequestParams,
        context: RequestContext<RoleServer>,
    ) -> impl Future<Output = Result<InitializeResult, ErrorData>> + Send + '_ {
        if protocol_uses_discovery(request.protocol_version.as_str()) {
            return std::future::ready(Err(ErrorData::new(
                ErrorCode::METHOD_NOT_FOUND,
                "initialize is not available in MCP 2026-07-28; use server/discover",
                None,
            )));
        }
        context.peer.set_peer_info(request.clone());
        std::future::ready(self.negotiate_initialize(&request))
    }

    fn supported_protocol_versions(&self) -> Cow<'static, [ProtocolVersion]> {
        Cow::Borrowed(&[
            ProtocolVersion::V_2026_07_28,
            ProtocolVersion::V_2025_11_25,
            ProtocolVersion::V_2025_06_18,
            ProtocolVersion::V_2025_03_26,
        ])
    }

    fn get_info(&self) -> ServerConfig {
        let mut capabilities = ServerCapabilities::builder()
            .enable_experimental()
            .enable_tools()
            .enable_resources()
            .build();
        if let Some(resources) = capabilities.resources.as_mut() {
            resources.subscribe = Some(false);
            resources.list_changed = Some(false);
        }
        if let Some(tools) = capabilities.tools.as_mut() {
            tools.list_changed = Some(false);
        }
        if self.protocol_profile == ProtocolProfile::Http2026 {
            capabilities.prompts = Some(Default::default());
            if let Some(prompts) = capabilities.prompts.as_mut() {
                prompts.list_changed = Some(false);
            }
        }
        ServerConfig::new(capabilities)
            .with_server_info(Implementation::new(SERVER_NAME, env!("CARGO_PKG_VERSION")))
    }

    async fn list_tools(
        &self,
        _request: Option<PaginatedRequestParams>,
        _context: RequestContext<RoleServer>,
    ) -> Result<ListToolsResult, ErrorData> {
        let result = ListToolsResult::with_all_items(self.configured_tools());
        Ok(if self.protocol_profile == ProtocolProfile::Http2026 {
            result.with_ttl_ms(0).with_cache_scope(CacheScope::Private)
        } else {
            result
        })
    }

    async fn call_tool(
        &self,
        request: CallToolRequestParams,
        _context: RequestContext<RoleServer>,
    ) -> Result<CallToolResponse, ErrorData> {
        let mut arguments = request.arguments.unwrap_or_default();
        let result = self
            .invoke_result(&request.name, &mut arguments)
            .await
            .map_err(InvocationError::protocol_error)?;
        let mut response = result.structured_content.map_or_else(
            || CallToolResult::success(Vec::new()),
            CallToolResult::structured,
        );
        response.content = vec![ContentBlock::text(result.text)];
        Ok(response.into())
    }

    async fn list_resources(
        &self,
        _request: Option<PaginatedRequestParams>,
        _context: RequestContext<RoleServer>,
    ) -> Result<ListResourcesResult, ErrorData> {
        let result = ListResourcesResult::with_all_items(resource_specs());
        Ok(if self.protocol_profile == ProtocolProfile::Http2026 {
            result.with_ttl_ms(0).with_cache_scope(CacheScope::Private)
        } else {
            result
        })
    }

    async fn list_prompts(
        &self,
        _request: Option<PaginatedRequestParams>,
        _context: RequestContext<RoleServer>,
    ) -> Result<ListPromptsResult, ErrorData> {
        let result = ListPromptsResult::with_all_items(Vec::new());
        Ok(if self.protocol_profile == ProtocolProfile::Http2026 {
            result.with_ttl_ms(0).with_cache_scope(CacheScope::Private)
        } else {
            result
        })
    }

    async fn read_resource(
        &self,
        request: ReadResourceRequestParams,
        _context: RequestContext<RoleServer>,
    ) -> Result<ReadResourceResponse, ErrorData> {
        let uri = request.uri;
        let text = self
            .read_result(&uri)
            .map_err(InvocationError::protocol_error)?;
        let mime = match uri.as_str() {
            "compass://report" => "text/markdown",
            "compass://orientation" => "application/json",
            "compass://graph-insights" => "application/json",
            _ => "text/plain",
        };
        let result =
            ReadResourceResult::new(vec![ResourceContents::text(text, uri).with_mime_type(mime)]);
        Ok(if self.protocol_profile == ProtocolProfile::Http2026 {
            result
                .with_ttl_ms(0)
                .with_cache_scope(CacheScope::Private)
                .into()
        } else {
            result.into()
        })
    }
}

struct ToolInvocation {
    text: String,
    structured_content: Option<Value>,
}

impl CompassMcp {
    async fn invoke_result(
        &self,
        name: &str,
        arguments: &mut Map<String, Value>,
    ) -> Result<ToolInvocation, InvocationError> {
        if !self.configured_tools().iter().any(|tool| tool.name == name) {
            return Err(InvocationError::InvalidParams(format!(
                "unknown tool: {name}"
            )));
        }
        if name == "query_graph" {
            code_query::validate_query_graph_arguments(arguments)?;
        }
        let project_path = match arguments.remove("project_path") {
            Some(Value::String(path)) => Some(path),
            Some(_) => {
                return Err(InvocationError::InvalidParams(
                    "project_path must be a string".to_owned(),
                ));
            }
            None => None,
        };
        if matches!(name, "inspect_agent_graph" | "apply_agent_graph") {
            return self.invoke_agent_graph(name, arguments, project_path.as_deref());
        }
        if matches!(name, "review_pull_request" | "pr_readiness") {
            let root = self
                .store
                .source_root(project_path.as_deref())
                .map_err(InvocationError::Internal)?;
            return invoke_review_tool(arguments, &root, name == "pr_readiness");
        }
        if name == "task_context" {
            let graph_path = self
                .store
                .resolve(project_path.as_deref())
                .map_err(InvocationError::Internal)?;
            let root = self
                .store
                .source_root(project_path.as_deref())
                .map_err(InvocationError::Internal)?;
            let use_surreal = self.store.selects_surreal(&graph_path)?;
            if use_surreal {
                #[cfg(any(
                    feature = "surreal-surrealkv",
                    feature = "surreal-rocksdb",
                    feature = "surreal-remote"
                ))]
                {
                    return invoke_surreal_task_context(
                        &self.store,
                        arguments,
                        &graph_path,
                        &root,
                        self.agent_graph.as_deref(),
                    )
                    .await;
                }
                #[cfg(not(any(
                    feature = "surreal-surrealkv",
                    feature = "surreal-rocksdb",
                    feature = "surreal-remote"
                )))]
                unreachable!("Surreal selection is false without an engine feature");
            }
            let context = if self.store.selects_store(&graph_path) {
                None
            } else {
                Some(
                    self.store
                        .load(project_path.as_deref())
                        .map_err(InvocationError::Internal)?,
                )
            };
            return invoke_task_context(
                &self.store,
                arguments,
                &graph_path,
                &root,
                context.as_deref(),
                self.agent_graph.as_deref(),
            );
        }
        if name == "query_graph" && natural_discovery_requested(arguments) {
            let graph_path = self
                .store
                .resolve(project_path.as_deref())
                .map_err(InvocationError::Internal)?;
            let use_surreal = self.store.selects_surreal(&graph_path)?;
            if use_surreal {
                #[cfg(any(
                    feature = "surreal-surrealkv",
                    feature = "surreal-rocksdb",
                    feature = "surreal-remote"
                ))]
                {
                    return invoke_surreal_typed_tool(&self.store, name, arguments, &graph_path)
                        .await;
                }
                #[cfg(not(any(
                    feature = "surreal-surrealkv",
                    feature = "surreal-rocksdb",
                    feature = "surreal-remote"
                )))]
                unreachable!("Surreal selection is false without an engine feature");
            }
            if self.store.selects_store(&graph_path) {
                return invoke_discovery_tool(&self.store, arguments, &graph_path, None);
            }
        }
        let typed_query = matches!(
            name,
            "search_symbols"
                | "get_callers"
                | "get_callees"
                | "get_impact"
                | "explore_code"
                | "get_node"
        );
        if typed_query {
            let graph_path = self
                .store
                .resolve(project_path.as_deref())
                .map_err(InvocationError::Internal)?;
            let use_surreal = self.store.selects_surreal(&graph_path)?;
            if use_surreal {
                #[cfg(any(
                    feature = "surreal-surrealkv",
                    feature = "surreal-rocksdb",
                    feature = "surreal-remote"
                ))]
                {
                    return invoke_surreal_typed_tool(&self.store, name, arguments, &graph_path)
                        .await;
                }
                #[cfg(not(any(
                    feature = "surreal-surrealkv",
                    feature = "surreal-rocksdb",
                    feature = "surreal-remote"
                )))]
                unreachable!("Surreal selection is false without an engine feature");
            }
            if self.store.selects_store(&graph_path) {
                return invoke_typed_tool(&self.store, name, arguments, &graph_path, None);
            }
        }
        let context = self
            .store
            .load(project_path.as_deref())
            .map_err(InvocationError::Internal)?;
        if name == "query_graph" && should_route_natural_query(arguments, &context)? {
            return invoke_discovery_tool(&self.store, arguments, &context.path, Some(&context));
        }
        if typed_query {
            return invoke_typed_tool(&self.store, name, arguments, &context.path, Some(&context));
        }
        Ok(ToolInvocation {
            text: invoke_tool(name, arguments, &context).map_err(InvocationError::InvalidParams)?,
            structured_content: None,
        })
    }

    fn invoke_agent_graph(
        &self,
        name: &str,
        arguments: &mut Map<String, Value>,
        project_path: Option<&str>,
    ) -> Result<ToolInvocation, InvocationError> {
        let config = self.agent_graph.as_deref().ok_or_else(|| {
            InvocationError::InvalidParams("agent graph tools are not configured".to_owned())
        })?;
        let project_path = project_path.ok_or_else(|| {
            InvocationError::InvalidParams(
                "project_path is required for agent graph tools".to_owned(),
            )
        })?;
        let requested_root = PathBuf::from(project_path)
            .canonicalize()
            .map_err(|error| {
                InvocationError::InvalidParams(format!("cannot canonicalize project_path: {error}"))
            })?;
        if !config.allowed_projects.contains(&requested_root) {
            return Err(InvocationError::InvalidParams(
                "project_path is outside the server-authorized allowlist".to_owned(),
            ));
        }
        let graph_path = self
            .store
            .resolve(Some(project_path))
            .map_err(InvocationError::Internal)?;
        let context = AgentGraphContext::open_current(
            &requested_root,
            &graph_path,
            config.non_git_state_root.as_deref(),
        )
        .map_err(agent_graph_invocation_error)?;
        match name {
            "inspect_agent_graph" => {
                invoke_agent_graph_read(&context, arguments, &graph_path, config.writes_enabled)
            }
            "apply_agent_graph" => {
                if !config.writes_enabled {
                    return Err(InvocationError::InvalidParams(
                        "agent graph writes are disabled".to_owned(),
                    ));
                }
                invoke_agent_graph_write(&context, config, arguments)
            }
            _ => Err(InvocationError::InvalidParams(format!(
                "unknown agent graph tool {name}"
            ))),
        }
    }
}

fn invoke_agent_graph_read(
    context: &AgentGraphContext,
    arguments: &Map<String, Value>,
    graph_path: &Path,
    writes_enabled: bool,
) -> Result<ToolInvocation, InvocationError> {
    reject_unknown_arguments(
        arguments,
        &[
            "operation",
            "overlay",
            "revision",
            "old_revision",
            "new_revision",
            "profile",
            "limit",
            "query",
            "base_nodes",
            "base_edges",
            "source_spans",
        ],
        "inspect_agent_graph",
    )?;
    let operation = string_argument(arguments, "operation")?;
    let overlay = OverlayId::parse(string_argument(arguments, "overlay")?.to_owned())
        .map_err(agent_graph_invocation_error)?;
    let result = match operation {
        "status" => {
            let active = context
                .active_revision(&overlay)
                .map_err(agent_graph_invocation_error)?;
            json!({
                "schema":"compass.agent-graph.status/1",
                "overlay":overlay,
                "baseGeneration":context.base_generation(),
                "activeRevision":active,
                "writesEnabled":writes_enabled
            })
        }
        "overlay" => {
            let revision = optional_revision(arguments, "revision")?;
            serialize_agent_read(context.read(ReadRequest::Overlay { overlay, revision }))?
        }
        "prepare" => {
            if arguments.contains_key("revision") {
                return Err(InvocationError::InvalidParams(
                    "prepare selects the active Overlay Revision automatically; do not pass revision"
                        .to_owned(),
                ));
            }
            let base_node_ids = string_array_argument(arguments, "base_nodes")?;
            let base_edge_ids = string_array_argument(arguments, "base_edges")?;
            let source_spans = arguments
                .get("source_spans")
                .cloned()
                .map(serde_json::from_value::<Vec<SourceSpanRequest>>)
                .transpose()
                .map_err(|error| {
                    InvocationError::InvalidParams(format!(
                        "source_spans must be strict source span requests: {error}"
                    ))
                })?
                .unwrap_or_default();
            serialize_agent_read(context.read(ReadRequest::PrepareIngestion {
                overlay,
                base_generation: context.base_generation().clone(),
                request: IngestionPreparationRequest {
                    base_node_ids,
                    base_edge_ids,
                    source_spans,
                },
            }))?
        }
        "effective" => {
            let revision = required_revision(arguments, "revision")?;
            let profile = match arguments
                .get("profile")
                .and_then(Value::as_str)
                .unwrap_or("augment")
            {
                "augment" => CompositionProfile::Augment,
                "curated" => CompositionProfile::Curated,
                _ => {
                    return Err(InvocationError::InvalidParams(
                        "profile must be augment or curated".to_owned(),
                    ));
                }
            };
            serialize_agent_read(context.read(ReadRequest::EffectiveGraph {
                overlay,
                revision,
                profile,
            }))?
        }
        "query" => {
            let revision = required_revision(arguments, "revision")?;
            let query = string_argument(arguments, "query")?;
            if query.len() > 16_384 || query.chars().any(char::is_control) {
                return Err(InvocationError::InvalidParams(
                    "query must contain at most 16384 non-control bytes".to_owned(),
                ));
            }
            let profile = match arguments
                .get("profile")
                .and_then(Value::as_str)
                .unwrap_or("augment")
            {
                "augment" => CompositionProfile::Augment,
                "curated" => CompositionProfile::Curated,
                _ => {
                    return Err(InvocationError::InvalidParams(
                        "profile must be augment or curated".to_owned(),
                    ));
                }
            };
            let effective = match context
                .read(ReadRequest::EffectiveGraph {
                    overlay,
                    revision,
                    profile,
                })
                .map_err(agent_graph_invocation_error)?
            {
                ReadResult::EffectiveGraph(value) => value,
                _ => {
                    return Err(InvocationError::Internal(
                        "Agent Graph effective read returned the wrong result type".to_owned(),
                    ));
                }
            };
            let cache_root = graph_path
                .parent()
                .unwrap_or_else(|| Path::new("."))
                .join("cache");
            let engine = compass_query::open_with_verified_document(
                effective.graph,
                effective.effective_identity.as_str().to_owned(),
                graph_path,
                None,
                &cache_root,
            )
            .map_err(|error| InvocationError::Internal(error.to_string()))?;
            serde_json::to_value(
                engine
                    .search(compass_model::query_contract::SearchRequest {
                        query: query.to_owned(),
                        limits: compass_model::query_contract::CodeQueryLimits::default(),
                    })
                    .map_err(|error| InvocationError::Internal(error.to_string()))?,
            )
            .map_err(|error| InvocationError::Internal(error.to_string()))?
        }
        "history" => {
            let limit = arguments
                .get("limit")
                .and_then(Value::as_u64)
                .unwrap_or(100);
            let limit = usize::try_from(limit)
                .map_err(|_| InvocationError::InvalidParams("limit is too large".to_owned()))?;
            serialize_agent_read(context.read(ReadRequest::History { overlay, limit }))?
        }
        "audit" => serialize_agent_read(context.read(ReadRequest::Audit {
            revision: required_revision(arguments, "revision")?,
        }))?,
        "diff" => serialize_agent_read(context.read(ReadRequest::Diff {
            overlay,
            old: required_revision(arguments, "old_revision")?,
            new: required_revision(arguments, "new_revision")?,
        }))?,
        "rebase_plan" => serialize_agent_read(context.read(ReadRequest::PrepareRebase {
            overlay,
            source_revision: required_revision(arguments, "revision")?,
            target_base_generation: context.base_generation().clone(),
        }))?,
        _ => {
            return Err(InvocationError::InvalidParams(format!(
                "unknown inspect operation {operation}"
            )));
        }
    };
    Ok(ToolInvocation {
        text: format!("Agent Graph {operation} completed for an exact local context."),
        structured_content: Some(transport_envelope(result)?),
    })
}

fn serialize_agent_read(
    result: Result<ReadResult, compass_agent_graph::AgentGraphError>,
) -> Result<Value, InvocationError> {
    let result = result.map_err(agent_graph_invocation_error)?;
    serde_json::to_value(match result {
        ReadResult::Overlay {
            revision,
            manifest,
            state,
        } => json!({
            "schema":"compass.agent-graph.overlay-read/1",
            "revision":revision,
            "manifest":manifest,
            "state":state
        }),
        ReadResult::EffectiveGraph(value) => serde_json::to_value(value)
            .map_err(|error| InvocationError::Internal(error.to_string()))?,
        ReadResult::IngestionPreparation(value) => serde_json::to_value(value)
            .map_err(|error| InvocationError::Internal(error.to_string()))?,
        ReadResult::History(value) => serde_json::to_value(value)
            .map_err(|error| InvocationError::Internal(error.to_string()))?,
        ReadResult::Diff(value) => serde_json::to_value(value)
            .map_err(|error| InvocationError::Internal(error.to_string()))?,
        ReadResult::RebasePlan(value) => serde_json::to_value(value)
            .map_err(|error| InvocationError::Internal(error.to_string()))?,
        ReadResult::Audit(value) => serde_json::to_value(value)
            .map_err(|error| InvocationError::Internal(error.to_string()))?,
    })
    .map_err(|error| InvocationError::Internal(error.to_string()))
}

fn string_array_argument(
    arguments: &Map<String, Value>,
    name: &str,
) -> Result<Vec<String>, InvocationError> {
    let Some(value) = arguments.get(name) else {
        return Ok(Vec::new());
    };
    let values = value.as_array().ok_or_else(|| {
        InvocationError::InvalidParams(format!("{name} must be an array of strings"))
    })?;
    values
        .iter()
        .map(|value| {
            let value = value.as_str().ok_or_else(|| {
                InvocationError::InvalidParams(format!("{name} must contain only strings"))
            })?;
            if value.is_empty() || value.len() > 4_096 || value.chars().any(char::is_control) {
                return Err(InvocationError::InvalidParams(format!(
                    "{name} values must contain 1..=4096 non-control bytes"
                )));
            }
            Ok(value.to_owned())
        })
        .collect()
}
fn invoke_agent_graph_write(
    context: &AgentGraphContext,
    config: &AgentGraphMcpConfig,
    arguments: &Map<String, Value>,
) -> Result<ToolInvocation, InvocationError> {
    reject_unknown_arguments(arguments, &["request_type", "request"], "apply_agent_graph")?;
    let request_type = string_argument(arguments, "request_type")?;
    let request = arguments
        .get("request")
        .ok_or_else(|| InvocationError::InvalidParams("request is required".to_owned()))?;
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_err(|error| InvocationError::Internal(format!("system clock is invalid: {error}")))?
        .as_secs();
    let authority = WriteAuthority::explicitly_enabled(context.repository_id().clone());
    let mut permissions = BTreeSet::from([
        OperationPermission::PutAssertion,
        OperationPermission::RetractAssertion,
        OperationPermission::PutChallenge,
        OperationPermission::RetractChallenge,
    ]);
    let receipt = match request_type {
        "change_batch" => {
            let batch =
                serde_json::from_value::<ChangeBatch>(request.clone()).map_err(|error| {
                    InvocationError::InvalidParams(format!(
                        "request is not a strict change batch: {error}"
                    ))
                })?;
            if &batch.base_generation != context.base_generation() {
                return Err(InvocationError::InvalidParams(
                    "batch Base Generation does not match the selected exact graph".to_owned(),
                ));
            }
            let request_digest =
                compass_agent_graph::canonical_digest("compass.agent-graph.mcp-request/1", &batch)
                    .map_err(agent_graph_invocation_error)?;
            let attestation = compass_agent_graph::WriteAttestation::new("mcp")
                .map_err(agent_graph_invocation_error)?
                .with_request_digest(request_digest);
            let grant = authority
                .mint_attested(
                    config.principal.clone(),
                    batch.overlay.clone(),
                    batch.base_generation.clone(),
                    batch.expected_revision.clone(),
                    permissions,
                    config.masks_enabled,
                    now.saturating_add(300),
                    AgentGraphLimits::default(),
                    attestation,
                )
                .map_err(agent_graph_invocation_error)?;
            context
                .apply(&grant, batch)
                .map_err(agent_graph_invocation_error)?
        }
        "rebase_commit" => {
            permissions.insert(OperationPermission::CommitRebase);
            let request = serde_json::from_value::<RebaseCommitRequest>(request.clone()).map_err(
                |error| {
                    InvocationError::InvalidParams(format!(
                        "request is not a strict rebase commit: {error}"
                    ))
                },
            )?;
            if &request.plan.target_base_generation != context.base_generation() {
                return Err(InvocationError::InvalidParams(
                    "rebase target does not match the selected exact graph".to_owned(),
                ));
            }
            let request_digest = compass_agent_graph::canonical_digest(
                "compass.agent-graph.mcp-request/1",
                &request,
            )
            .map_err(agent_graph_invocation_error)?;
            let attestation = compass_agent_graph::WriteAttestation::new("mcp")
                .map_err(agent_graph_invocation_error)?
                .with_request_digest(request_digest);
            let grant = authority
                .mint_attested(
                    config.principal.clone(),
                    request.plan.overlay.clone(),
                    request.plan.target_base_generation.clone(),
                    Some(request.plan.source_revision.clone()),
                    permissions,
                    config.masks_enabled,
                    now.saturating_add(300),
                    AgentGraphLimits::default(),
                    attestation,
                )
                .map_err(agent_graph_invocation_error)?;
            context
                .commit_rebase(&grant, request)
                .map_err(agent_graph_invocation_error)?
        }
        _ => {
            return Err(InvocationError::InvalidParams(
                "request_type must be change_batch or rebase_commit".to_owned(),
            ));
        }
    };
    let value = serde_json::to_value(&receipt)
        .map_err(|error| InvocationError::Internal(error.to_string()))?;
    Ok(ToolInvocation {
        text: format!(
            "Committed Agent Graph revision {}.",
            receipt.revision.as_digest().as_str()
        ),
        structured_content: Some(transport_envelope(value)?),
    })
}

fn agent_graph_invocation_error(error: compass_agent_graph::AgentGraphError) -> InvocationError {
    let encoded = serde_json::to_string(&error).unwrap_or_else(|_| error.to_string());
    InvocationError::InvalidParams(encoded)
}

fn required_revision(
    arguments: &Map<String, Value>,
    name: &str,
) -> Result<OverlayRevisionId, InvocationError> {
    let value = string_argument(arguments, name)?;
    Ok(OverlayRevisionId(
        compass_agent_graph::Digest::parse(value.to_owned())
            .map_err(agent_graph_invocation_error)?,
    ))
}

fn optional_revision(
    arguments: &Map<String, Value>,
    name: &str,
) -> Result<Option<OverlayRevisionId>, InvocationError> {
    arguments.get(name).map_or(Ok(None), |value| {
        let value = value
            .as_str()
            .ok_or_else(|| InvocationError::InvalidParams(format!("{name} must be a string")))?;
        Ok(Some(OverlayRevisionId(
            compass_agent_graph::Digest::parse(value.to_owned())
                .map_err(agent_graph_invocation_error)?,
        )))
    })
}

fn reject_unknown_arguments(
    arguments: &Map<String, Value>,
    allowed: &[&str],
    tool_name: &str,
) -> Result<(), InvocationError> {
    for name in arguments.keys() {
        if !allowed.contains(&name.as_str()) {
            return Err(InvocationError::InvalidParams(format!(
                "unknown {tool_name} argument {name:?}"
            )));
        }
    }
    Ok(())
}

fn invoke_typed_tool(
    store: &GraphStore,
    name: &str,
    arguments: &Map<String, Value>,
    graph_path: &Path,
    context: Option<&GraphContext>,
) -> Result<ToolInvocation, InvocationError> {
    let engine = cached_typed_engine(store, graph_path, context)?;
    let engine = engine
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    let response = code_query::invoke_with_engine(name, arguments, &engine)?;
    let context = typed_agent_query_context(
        name,
        arguments,
        &response,
        engine.graph_identity(),
        engine.build_generation_identity(),
    );
    typed_query_invocation(response, context)
}

/// Build the shared `compass.mcp.tool-result/1` envelope for a typed code
/// query: the raw `compass.query/1` payload under `result`, its semantic
/// digest, and the `compass.query.agent-view/1` sibling. Every engine backend
/// goes through this function so the contract cannot drift between them.
fn typed_query_invocation(
    response: compass_model::query_contract::CodeQueryResponse,
    context: AgentQueryContext,
) -> Result<ToolInvocation, InvocationError> {
    let view = build_code_query_view(&response, context)
        .map_err(|error| InvocationError::Internal(error.to_string()))?;
    let text = render_agent_query_text(&view)
        .map_err(|error| InvocationError::Internal(error.to_string()))?;
    let semantic_result_digest = compass_query::code_query_response_digest(&response)
        .map_err(|error| InvocationError::Internal(error.to_string()))?;
    let max_response_bytes = response.limits.max_response_bytes;
    let view =
        serde_json::to_value(view).map_err(|error| InvocationError::Internal(error.to_string()))?;
    let envelope = transport_envelope_with_view(
        serde_json::to_value(response)
            .map_err(|error| InvocationError::Internal(error.to_string()))?,
        Some(&semantic_result_digest),
        Some(view),
    )?;
    // `max_response_bytes` bounds what the caller actually receives, so it is
    // measured after the agent view and transport fields are attached. The
    // query engine already bounded the semantic result; a result that fits
    // while its envelope does not is still a bound breach, and a distinct
    // error beats returning an oversized payload.
    enforce_structured_response_size(&envelope, max_response_bytes)?;
    Ok(ToolInvocation {
        text,
        structured_content: Some(envelope),
    })
}

/// Reject an encoded tool result that exceeds the caller's byte bound.
fn enforce_structured_response_size(value: &Value, maximum: u64) -> Result<(), InvocationError> {
    let actual = serde_json::to_vec(value)
        .map_err(|error| InvocationError::Internal(error.to_string()))?
        .len() as u64;
    if actual > maximum {
        return Err(InvocationError::Internal(format!(
            "query_response_too_large: query response is {actual} bytes after MCP envelope encoding; limit is {maximum}"
        )));
    }
    Ok(())
}

fn typed_agent_query_context(
    name: &str,
    arguments: &Map<String, Value>,
    response: &compass_model::query_contract::CodeQueryResponse,
    graph_identity: &str,
    build_generation_identity: &str,
) -> AgentQueryContext {
    let mut context = AgentQueryContext::new(
        AgentOperation::from(response.operation),
        graph_identity.to_owned(),
        build_generation_identity.to_owned(),
    );
    let operand = |role: AgentOperandRole, name: &str, context: AgentQueryContext| match arguments
        .get(name)
        .and_then(Value::as_str)
    {
        Some(value) => context.with_operand(role, value.to_owned()),
        None => context,
    };
    context = match name {
        "search_symbols" => operand(AgentOperandRole::Query, "query", context),
        "get_callers" | "get_callees" | "get_impact" => {
            operand(AgentOperandRole::Symbol, "symbol", context)
        }
        "get_node" => {
            let context = operand(AgentOperandRole::Source, "source", context);
            operand(AgentOperandRole::Target, "target", context)
        }
        "explore_code" => {
            let mut context = context;
            if let Some(values) = arguments.get("symbols").and_then(Value::as_array) {
                for value in values.iter().filter_map(Value::as_str) {
                    context = context.with_operand(AgentOperandRole::Symbol, value.to_owned());
                }
            }
            operand(AgentOperandRole::Root, "root", context)
        }
        _ => context,
    };
    context
}

#[cfg(any(
    feature = "surreal-surrealkv",
    feature = "surreal-rocksdb",
    feature = "surreal-remote"
))]
async fn invoke_surreal_typed_tool(
    store: &GraphStore,
    name: &str,
    arguments: &Map<String, Value>,
    graph_path: &Path,
) -> Result<ToolInvocation, InvocationError> {
    let engine = store
        .inner
        .surreal_queries
        .get(graph_path)
        .await
        .map_err(|error| InvocationError::Internal(error.to_string()))?;
    let response = code_query::invoke_with_surreal(name, arguments, &engine).await?;
    let reference = engine.reference();
    let mut context = typed_agent_query_context(
        name,
        arguments,
        &response,
        &reference.repository_id,
        &reference.generation_id,
    );
    if let Some(question) = arguments.get("question").and_then(Value::as_str) {
        context = context.with_question(question.to_owned());
    }
    typed_query_invocation(response, context)
}

