use axum::extract::{Request, State};
use axum::http::{HeaderValue, Method, StatusCode, header};
use axum::middleware::{self, Next};
use axum::response::{IntoResponse, Response};
use rmcp::ServiceExt;
use rmcp::transport::streamable_http_server::{
    StreamableHttpServerConfig, StreamableHttpService, session::local::LocalSessionManager,
};
use tokio::io::{AsyncBufReadExt, AsyncReadExt, AsyncWriteExt, BufReader};
use tokio_util::sync::CancellationToken;
use tower_http::limit::RequestBodyLimitLayer;

use crate::{
    AgentGraphMcpConfig, CompassMcp, SUPPORTED_PROTOCOL_VERSIONS, protocol_uses_discovery,
    supports_protocol,
};

/// Revision a request without an `MCP-Protocol-Version` header is taken to speak.
const LEGACY_DEFAULT_PROTOCOL_VERSION: &str = "2025-03-26";

const MAX_HTTP_REQUEST_BYTES: usize = 16 * 1024 * 1024;
const MAX_HTTP_RESPONSE_BYTES: usize = 64 * 1024 * 1024;
const MAX_STDIO_MESSAGE_BYTES: usize = 16 * 1024 * 1024;

/// Configuration for the Compass-compatible MCP Streamable HTTP transport.
#[derive(Clone, Debug)]
pub struct HttpOptions {
    pub graph_path: PathBuf,
    pub host: String,
    pub port: u16,
    pub api_key: Option<String>,
    /// Independent authenticated capability required for Agent Graph writes.
    pub write_api_key: Option<String>,
    pub agent_graph: Option<AgentGraphMcpConfig>,
    pub path: String,
    pub json_response: bool,
    pub stateless: bool,
    pub session_timeout: Option<Duration>,
    pub engine: compass_query::EngineSelection,
}

impl HttpOptions {
    #[must_use]
    pub fn new(graph_path: PathBuf) -> Self {
        Self {
            graph_path,
            host: "127.0.0.1".to_owned(),
            port: 8080,
            api_key: None,
            write_api_key: None,
            agent_graph: None,
            path: "/mcp".to_owned(),
            json_response: false,
            stateless: true,
            session_timeout: None,
            engine: compass_query::EngineSelection::Default,
        }
    }
}

#[derive(Clone)]
struct HttpGate {
    api_key: Option<Arc<[u8]>>,
    allowed_hosts: Arc<[String]>,
    write_api_key: Option<Arc<[u8]>>,
    convert_stateful_sse_to_json: bool,
}

/// Serve MCP over stdio while tolerating blank lines sent by desktop clients.
pub async fn serve_stdio(graph_path: PathBuf) -> Result<(), String> {
    serve_stdio_configured(graph_path, None).await
}

/// Serve MCP over stdio with an explicit Agent Graph policy. Writes remain absent when the
/// configuration is `None` or has `writes_enabled == false`.
pub async fn serve_stdio_configured(
    graph_path: PathBuf,
    agent_graph: Option<AgentGraphMcpConfig>,
) -> Result<(), String> {
    serve_stdio_configured_with_engine(
        graph_path,
        agent_graph,
        compass_query::EngineSelection::Default,
    )
    .await
}

pub async fn serve_stdio_configured_with_engine(
    graph_path: PathBuf,
    agent_graph: Option<AgentGraphMcpConfig>,
    engine: compass_query::EngineSelection,
) -> Result<(), String> {
    let (mut relay_write, relay_read) = tokio::io::duplex(64 * 1024);
    let relay = tokio::spawn(async move {
        let mut input = BufReader::new(tokio::io::stdin());
        let mut line = Vec::new();
        loop {
            line.clear();
            let count = (&mut input)
                .take((MAX_STDIO_MESSAGE_BYTES + 1) as u64)
                .read_until(b'\n', &mut line)
                .await
                .map_err(|error| error.to_string())?;
            if count == 0 {
                break;
            }
            if line.len() > MAX_STDIO_MESSAGE_BYTES {
                return Err(format!(
                    "MCP stdio message exceeds {MAX_STDIO_MESSAGE_BYTES} bytes"
                ));
            }
            if line.iter().any(|byte| !byte.is_ascii_whitespace()) {
                relay_write
                    .write_all(&line)
                    .await
                    .map_err(|error| error.to_string())?;
            }
        }
        Ok::<(), String>(())
    });
    let server = match agent_graph {
        Some(config) => CompassMcp::new_with_engine(graph_path, engine).with_agent_graph(config)?,
        None => CompassMcp::new_with_engine(graph_path, engine),
    };
    let running = server
        .serve((relay_read, tokio::io::stdout()))
        .await
        .map_err(|error| error.to_string())?;
    running.waiting().await.map_err(|error| error.to_string())?;
    relay.abort();
    Ok(())
}

/// Serve MCP over Streamable HTTP until Ctrl+C or process cancellation.
pub async fn serve_http(mut options: HttpOptions) -> Result<(), String> {
    if !options.path.starts_with('/') || options.path.contains('?') || options.path.contains('#') {
        return Err(
            "HTTP mount path must start with '/' and contain no query or fragment".to_owned(),
        );
    }
    options.api_key = options
        .api_key
        .take()
        .map(|key| key.trim().to_owned())
        .filter(|key| !key.is_empty());
    options.write_api_key = options
        .write_api_key
        .take()
        .map(|key| key.trim().to_owned())
        .filter(|key| !key.is_empty());
    if options
        .agent_graph
        .as_ref()
        .is_some_and(|config| config.writes_enabled)
    {
        if options.api_key.is_none() || options.write_api_key.is_none() {
            return Err("HTTP Agent Graph writes require both a read API key and a separate write capability key".to_owned());
        }
        if options.api_key == options.write_api_key {
            return Err(
                "HTTP Agent Graph read and write capability keys must be distinct".to_owned(),
            );
        }
    }

    let cancellation = CancellationToken::new();
    let router = build_http_router(&options, &cancellation)?;

    let bind_host = if options.host.is_empty() {
        "0.0.0.0"
    } else {
        &options.host
    };
    let listener = tokio::net::TcpListener::bind((bind_host, options.port))
        .await
        .map_err(|error| format!("could not bind {bind_host}:{}: {error}", options.port))?;
    let auth_note = if options.api_key.is_some() {
        "api-key required"
    } else {
        "no auth (set --api-key to require one)"
    };
    eprintln!(
        "compass MCP server (streamable-http) on http://{}:{}{} - {auth_note}",
        options.host, options.port, options.path
    );
    if is_wildcard_host(&options.host) && options.api_key.is_none() {
        eprintln!(
            "WARNING: binding {} with no api-key exposes the graph unauthenticated on the network. Set --api-key (or COMPASS_API_KEY).",
            if options.host.is_empty() {
                "0.0.0.0"
            } else {
                &options.host
            }
        );
    }

    let shutdown = cancellation.clone();
    let shutdown_signal = async move {
        tokio::select! {
            _ = tokio::signal::ctrl_c() => {}
            () = shutdown.cancelled_owned() => {}
        }
    };
    let result = axum::serve(listener, router)
        .with_graceful_shutdown(shutdown_signal)
        .await;
    cancellation.cancel();
    result.map_err(|error| error.to_string())
}

fn build_http_router(
    options: &HttpOptions,
    cancellation: &CancellationToken,
) -> Result<Router, String> {
    let manager = Arc::new(LocalSessionManager::default());
    let factory_graph = match options.agent_graph.clone() {
        Some(config) => {
            CompassMcp::new_http_with_engine(options.graph_path.clone(), options.engine)
                .with_agent_graph(config)
        }
        None => Ok(CompassMcp::new_http_with_engine(
            options.graph_path.clone(),
            options.engine,
        )),
    }?;
    let allowed_hosts = if is_wildcard_host(&options.host) {
        Vec::new()
    } else {
        allowed_hosts(&options.host, options.port)
    };
    // Legacy sessions apply only to revisions before `2026-07-28`; rmcp serves `2026-07-28`
    // statelessly regardless (SEP-2567). With them off, an older client got no
    // `Mcp-Session-Id` and was routed statelessly, where the metadata requirement below
    // rejects its ordinary requests, since pre-`2026-07-28` clients attach no per-request
    // metadata. On, older clients get a session and `2026-07-28` clients keep the strict
    // stateless path.
    let mut config = StreamableHttpServerConfig::default()
        .with_legacy_session_mode(true)
        .with_stateless_protocol_metadata_required(true)
        .with_json_response(options.json_response)
        .with_max_request_body_bytes(MAX_HTTP_REQUEST_BYTES)
        .with_cancellation_token(cancellation.child_token());
    if is_wildcard_host(&options.host) {
        config = config.disable_allowed_hosts();
    } else {
        config = config.with_allowed_hosts(allowed_hosts.clone());
    }
    let service = StreamableHttpService::new(move || Ok(factory_graph.clone()), manager, config);
    let gate = HttpGate {
        api_key: options
            .api_key
            .as_ref()
            .map(|key| Arc::<[u8]>::from(key.as_bytes())),
        allowed_hosts: allowed_hosts.into(),
        write_api_key: options
            .write_api_key
            .as_ref()
            .map(|key| Arc::<[u8]>::from(key.as_bytes())),
        // rmcp transport negotiation owns the response representation.
        convert_stateful_sse_to_json: false,
    };
    Ok(Router::new()
        .route_service(&options.path, service)
        .layer(RequestBodyLimitLayer::new(MAX_HTTP_REQUEST_BYTES))
        .layer(middleware::from_fn(bound_http_response))
        .layer(middleware::from_fn_with_state(gate, http_gate)))
}

async fn bound_http_response(request: Request, next: Next) -> Response {
    enforce_response_limit(next.run(request).await, MAX_HTTP_RESPONSE_BYTES)
}

fn enforce_response_limit(response: Response, limit: usize) -> Response {
    if response.body().size_hint().lower() > limit as u64 {
        return (
            StatusCode::INTERNAL_SERVER_ERROR,
            [(header::CONTENT_TYPE, "application/json")],
            serde_json::json!({
                "jsonrpc": "2.0",
                "id": serde_json::Value::Null,
                "error": {
                    "code": -32023,
                    "message": "MCP HTTP response exceeds the configured limit"
                }
            })
            .to_string(),
        )
            .into_response();
    }
    let (parts, body) = response.into_parts();
    let limited = http_body_util::Limited::new(body, limit);
    Response::from_parts(parts, Body::new(limited))
}

async fn http_gate(State(gate): State<HttpGate>, mut request: Request, next: Next) -> Response {
    if let Some(expected) = &gate.api_key {
        let provided = request
            .headers()
            .get("x-api-key")
            .map(HeaderValue::as_bytes)
            .or_else(|| bearer_token(request.headers().get(header::AUTHORIZATION)));
        if !provided.is_some_and(|value| constant_time_eq(value, expected)) {
            return (
                StatusCode::UNAUTHORIZED,
                [(header::CONTENT_TYPE, "application/json")],
                "{\"error\": \"unauthorized\"}",
            )
                .into_response();
        }
    }
    if let Some(response) = host_rejection(&request, &gate.allowed_hosts) {
        return response;
    }
    if request.method() == Method::POST {
        let had_protocol_header = request.headers().contains_key("mcp-protocol-version");
        normalize_header(&mut request, "mcp-protocol-version");
        normalize_header(&mut request, "mcp-method");
        normalize_header(&mut request, "mcp-name");
        // An absent header means `2025-03-26`, the rule rmcp's own validator applies
        // (`streamable_http_server/tower.rs`). Clients send no header on the `initialize` POST,
        // since the version travels in the body until negotiation completes, so treating
        // absence as unsupported would refuse every client's first request.
        let protocol_version = request
            .headers()
            .get("mcp-protocol-version")
            .and_then(|value| value.to_str().ok())
            .map(str::to_owned)
            .or_else(|| (!had_protocol_header).then(|| LEGACY_DEFAULT_PROTOCOL_VERSION.to_owned()));
        if !protocol_version.as_deref().is_some_and(supports_protocol) {
            let requested = protocol_version.map_or(serde_json::Value::Null, Into::into);
            return protocol_gate_error(
                request,
                StatusCode::BAD_REQUEST,
                -32022,
                "Unsupported protocol version",
                Some(serde_json::json!({
                    "supported": SUPPORTED_PROTOCOL_VERSIONS,
                    "requested": requested,
                })),
            )
            .await;
        }
        // `2026-07-28` adds routing headers (SEP-2243) and discovery (SEP-2575).
        // Older clients use initialize without these headers.
        let uses_discovery = protocol_version
            .as_deref()
            .is_some_and(protocol_uses_discovery);
        if uses_discovery {
            let method = request
                .headers()
                .get("mcp-method")
                .and_then(|value| value.to_str().ok())
                .map(str::to_owned);
            if method.is_none() {
                return protocol_gate_error(
                    request,
                    StatusCode::BAD_REQUEST,
                    -32020,
                    "missing required Mcp-Method header",
                    None,
                )
                .await;
            }
            if method.as_deref() == Some("initialize") {
                return protocol_gate_error(
                    request,
                    StatusCode::NOT_FOUND,
                    -32601,
                    "initialize is not available in MCP 2026-07-28; use server/discover",
                    None,
                )
                .await;
            }
        }
    }
    let method = request.method().clone();
    if method == Method::POST && gate.write_api_key.is_some() {
        let provided = request
            .headers()
            .get("x-compass-write-key")
            .map(|value| value.as_bytes().to_vec());
        let (parts, body) = request.into_parts();
        let bytes = match axum::body::to_bytes(body, MAX_HTTP_REQUEST_BYTES).await {
            Ok(bytes) => bytes,
            Err(_) => {
                return (
                    StatusCode::PAYLOAD_TOO_LARGE,
                    [(header::CONTENT_TYPE, "application/json")],
                    "{\"error\": \"request_too_large\"}",
                )
                    .into_response();
            }
        };
        let is_write = serde_json::from_slice::<serde_json::Value>(&bytes)
            .ok()
            .is_some_and(|value| contains_agent_graph_write(&value));
        if is_write
            && !provided.as_deref().is_some_and(|value| {
                gate.write_api_key
                    .as_ref()
                    .is_some_and(|expected| constant_time_eq(value, expected))
            })
        {
            return (
                StatusCode::FORBIDDEN,
                [(header::CONTENT_TYPE, "application/json")],
                "{\"error\": \"write_capability_required\"}",
            )
                .into_response();
        }
        request = Request::from_parts(parts, Body::from(bytes));
    }
    let response = next.run(request).await;
    if gate.convert_stateful_sse_to_json && method == Method::POST {
        return sse_response_to_json(response).await;
    }
    response
}

fn normalize_header(request: &mut Request, name: &'static str) {
    let normalized = request
        .headers()
        .get(name)
        .and_then(|value| value.to_str().ok())
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .and_then(|value| HeaderValue::from_str(value).ok());
    if let Some(value) = normalized {
        request.headers_mut().insert(name, value);
    } else {
        request.headers_mut().remove(name);
    }
}

fn host_rejection(request: &Request, allowed_hosts: &[String]) -> Option<Response> {
    if allowed_hosts.is_empty() {
        return None;
    }
    // Mirror rmcp's effective-authority policy: an explicit Host header wins
    // over URI authority, and a portless allowlist entry permits every port for
    // that normalized host. Keeping this gate identical ensures DNS-rebinding
    // rejection happens before Compass emits protocol diagnostics; rmcp repeats
    // the check inside the service as defense in depth.
    let authority = if let Some(host) = request.headers().get(header::HOST) {
        let Ok(host) = host.to_str() else {
            return Some(
                (
                    StatusCode::BAD_REQUEST,
                    "Bad Request: Invalid Host header encoding",
                )
                    .into_response(),
            );
        };
        let Ok(authority) = axum::http::uri::Authority::try_from(host) else {
            return Some(
                (StatusCode::BAD_REQUEST, "Bad Request: Invalid Host header").into_response(),
            );
        };
        authority
    } else if let Some(authority) = request.uri().authority().cloned() {
        authority
    } else {
        return Some((StatusCode::BAD_REQUEST, "Bad Request: missing Host header").into_response());
    };
    let host = normalize_host(authority.host());
    let port = authority.port_u16();
    let allowed = allowed_hosts.iter().any(|candidate| {
        let candidate = candidate.trim();
        if candidate.is_empty() {
            return false;
        }
        if let Ok(authority) = axum::http::uri::Authority::try_from(candidate) {
            normalize_host(authority.host()) == host
                && authority
                    .port_u16()
                    .is_none_or(|allowed| Some(allowed) == port)
        } else {
            normalize_host(candidate) == host
        }
    });
    if allowed {
        None
    } else {
        Some(
            (
                StatusCode::FORBIDDEN,
                "Forbidden: Host header is not allowed",
            )
                .into_response(),
        )
    }
}

fn normalize_host(host: &str) -> String {
    host.trim_matches('[')
        .trim_matches(']')
        .to_ascii_lowercase()
}

async fn protocol_gate_error(
    request: Request,
    status: StatusCode,
    code: i32,
    message: &str,
    data: Option<serde_json::Value>,
) -> Response {
    let (_, body) = request.into_parts();
    let id = axum::body::to_bytes(body, MAX_HTTP_REQUEST_BYTES)
        .await
        .ok()
        .and_then(|bytes| serde_json::from_slice::<serde_json::Value>(&bytes).ok())
        .and_then(|value| value.get("id").cloned())
        .unwrap_or(serde_json::Value::Null);
    let mut error = serde_json::json!({"code": code, "message": message});
    if let Some(data) = data {
        error["data"] = data;
    }
    (
        status,
        [(header::CONTENT_TYPE, "application/json")],
        serde_json::json!({
            "jsonrpc": "2.0",
            "id": id,
            "error": error,
        })
        .to_string(),
    )
        .into_response()
}

fn contains_agent_graph_write(value: &serde_json::Value) -> bool {
    match value {
        serde_json::Value::Array(values) => values.iter().any(contains_agent_graph_write),
        serde_json::Value::Object(object) => {
            object.get("method").and_then(serde_json::Value::as_str) == Some("tools/call")
                && object
                    .get("params")
                    .and_then(serde_json::Value::as_object)
                    .and_then(|params| params.get("name"))
                    .and_then(serde_json::Value::as_str)
                    == Some("apply_agent_graph")
        }
        _ => false,
    }
}

fn bearer_token(value: Option<&HeaderValue>) -> Option<&[u8]> {
    let value = value?.as_bytes();
    let separator = value.iter().position(|byte| *byte == b' ')?;
    let (scheme, rest) = value.split_at(separator);
    if !scheme.eq_ignore_ascii_case(b"bearer") {
        return None;
    }
    let token = rest.get(1..)?;
    let start = token.iter().position(|byte| !byte.is_ascii_whitespace())?;
    let end = token.iter().rposition(|byte| !byte.is_ascii_whitespace())?;
    token.get(start..=end)
}

fn constant_time_eq(provided: &[u8], expected: &[u8]) -> bool {
    let length = provided.len().max(expected.len());
    let mut difference = provided.len() ^ expected.len();
    for index in 0..length {
        difference |= usize::from(provided.get(index).copied().unwrap_or_default())
            ^ usize::from(expected.get(index).copied().unwrap_or_default());
    }
    difference == 0
}

async fn sse_response_to_json(response: Response) -> Response {
    let is_sse = response
        .headers()
        .get(header::CONTENT_TYPE)
        .and_then(|value| value.to_str().ok())
        .is_some_and(|value| value.starts_with("text/event-stream"));
    if !is_sse {
        return response;
    }
    let (mut parts, body) = response.into_parts();
    let Ok(bytes) = axum::body::to_bytes(body, MAX_HTTP_RESPONSE_BYTES).await else {
        return (
            StatusCode::INTERNAL_SERVER_ERROR,
            "MCP response exceeded the server limit",
        )
            .into_response();
    };
    let payload = bytes
        .split(|byte| *byte == b'\n')
        .filter_map(|line| line.strip_prefix(b"data:"))
        .map(trim_ascii)
        .find(|line| serde_json::from_slice::<serde_json::Value>(line).is_ok());
    let Some(payload) = payload else {
        return Response::from_parts(parts, Body::from(bytes));
    };
    parts.headers.insert(
        header::CONTENT_TYPE,
        HeaderValue::from_static("application/json"),
    );
    parts.headers.remove(header::CONTENT_LENGTH);
    Response::from_parts(parts, Body::from(payload.to_vec()))
}

fn trim_ascii(mut value: &[u8]) -> &[u8] {
    while value.first().is_some_and(u8::is_ascii_whitespace) {
        value = &value[1..];
    }
    while value.last().is_some_and(u8::is_ascii_whitespace) {
        value = &value[..value.len().saturating_sub(1)];
    }
    value
}

fn is_wildcard_host(host: &str) -> bool {
    matches!(host, "" | "0.0.0.0" | "::")
}

fn allowed_hosts(host: &str, port: u16) -> Vec<String> {
    let mut hosts = vec![
        host.to_owned(),
        "localhost".to_owned(),
        "127.0.0.1".to_owned(),
    ];
    hosts.extend(
        [host, "localhost", "127.0.0.1"]
            .into_iter()
            .map(|name| format_authority(name, port)),
    );
    hosts.sort();
    hosts.dedup();
    hosts
}

fn format_authority(host: &str, port: u16) -> String {
    if host.contains(':') && !host.starts_with('[') {
        format!("[{host}]:{port}")
    } else {
        format!("{host}:{port}")
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;
    use std::net::SocketAddr;

    use serde_json::Value;
    use tokio::io::{AsyncReadExt, AsyncWriteExt};

    const INITIALIZE: &str = r#"{"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2025-03-26","capabilities":{},"clientInfo":{"name":"test","version":"0"}}}"#;

    #[test]
    fn api_keys_compare_without_early_exit() {
        assert!(constant_time_eq(b"secret", b"secret"));
        assert!(!constant_time_eq(b"secrex", b"secret"));
        assert!(!constant_time_eq(b"secret-long", b"secret"));
    }

    #[test]
    fn bearer_scheme_is_case_insensitive_and_token_is_trimmed() {
        let value = HeaderValue::from_static("bEaReR   secret  ");
        assert_eq!(bearer_token(Some(&value)), Some(b"secret".as_slice()));
        assert_eq!(bearer_token(None), None);
        assert_eq!(
            bearer_token(Some(&HeaderValue::from_static("Basic secret"))),
            None
        );
        assert_eq!(
            bearer_token(Some(&HeaderValue::from_static("Bearer"))),
            None
        );
        assert_eq!(
            bearer_token(Some(&HeaderValue::from_static("Bearer    "))),
            None
        );
    }

    #[test]
    fn local_bind_hosts_match_python_security_policy() {
        let hosts = allowed_hosts("127.0.0.1", 8080);
        assert!(hosts.iter().any(|host| host == "localhost:8080"));
        assert!(hosts.iter().any(|host| host == "127.0.0.1"));
        assert_eq!(format_authority("::1", 9000), "[::1]:9000");
        assert_eq!(format_authority("[::1]", 9000), "[::1]:9000");
        assert!(is_wildcard_host(""));
        assert!(is_wildcard_host("0.0.0.0"));
        assert!(is_wildcard_host("::"));
        assert!(!is_wildcard_host("localhost"));
        assert_eq!(trim_ascii(b" \t value \r\n"), b"value");
        assert!(trim_ascii(b" \t\r\n").is_empty());
    }

    #[test]
    fn only_the_closed_agent_mutation_tool_requires_write_capability() {
        assert!(contains_agent_graph_write(&serde_json::json!({
            "jsonrpc":"2.0",
            "id":1,
            "method":"tools/call",
            "params":{"name":"apply_agent_graph","arguments":{}}
        })));
        assert!(!contains_agent_graph_write(&serde_json::json!({
            "jsonrpc":"2.0",
            "id":2,
            "method":"tools/call",
            "params":{"name":"inspect_agent_graph","arguments":{}}
        })));
    }

    #[tokio::test]
    async fn http_agent_writes_require_distinct_read_and_write_credentials()
    -> Result<(), Box<dyn std::error::Error>> {
        let project = tempfile::tempdir()?;
        let mut options = HttpOptions::new(project.path().join("missing.json"));
        options.agent_graph = Some(crate::AgentGraphMcpConfig {
            writes_enabled: true,
            masks_enabled: false,
            principal: compass_agent_graph::PrincipalId::parse("principal:http-test")?,
            allowed_projects: std::collections::BTreeSet::from([project.path().canonicalize()?]),
            non_git_state_root: Some(project.path().join("agent-state")),
        });
        let error = serve_http(options.clone())
            .await
            .err()
            .ok_or("missing auth accepted")?;
        assert!(error.contains("both a read API key and a separate write capability key"));
        options.api_key = Some("same".to_owned());
        options.write_api_key = Some("same".to_owned());
        let error = serve_http(options)
            .await
            .err()
            .ok_or("shared auth accepted")?;
        assert!(error.contains("must be distinct"));
        Ok(())
    }

    #[tokio::test]
    async fn sse_conversion_preserves_non_sse_and_recovers_json_payloads()
    -> Result<(), Box<dyn std::error::Error>> {
        let plain = Response::builder()
            .status(StatusCode::ACCEPTED)
            .header(header::CONTENT_TYPE, "application/json")
            .body(Body::from("{\"plain\":true}"))?;
        let plain = sse_response_to_json(plain).await;
        assert_eq!(plain.status(), StatusCode::ACCEPTED);
        assert_eq!(
            axum::body::to_bytes(plain.into_body(), 1024).await?,
            "{\"plain\":true}"
        );

        let sse = Response::builder()
            .header(header::CONTENT_TYPE, "text/event-stream; charset=utf-8")
            .header(header::CONTENT_LENGTH, "999")
            .body(Body::from(
                "event: message\ndata: not-json\ndata:  {\"jsonrpc\":\"2.0\",\"id\":1}  \n\n",
            ))?;
        let converted = sse_response_to_json(sse).await;
        assert_eq!(
            converted.headers().get(header::CONTENT_TYPE),
            Some(&HeaderValue::from_static("application/json"))
        );
        assert!(!converted.headers().contains_key(header::CONTENT_LENGTH));
        assert_eq!(
            axum::body::to_bytes(converted.into_body(), 1024).await?,
            "{\"jsonrpc\":\"2.0\",\"id\":1}"
        );

        let invalid = Response::builder()
            .header(header::CONTENT_TYPE, "text/event-stream")
            .body(Body::from("event: ping\ndata: invalid\n\n"))?;
        let invalid = sse_response_to_json(invalid).await;
        assert_eq!(
            axum::body::to_bytes(invalid.into_body(), 1024).await?,
            "event: ping\ndata: invalid\n\n"
        );
        Ok(())
    }

    #[tokio::test]
    async fn http_configuration_rejects_bad_mounts_and_unbindable_hosts() {
        let mut options = HttpOptions::new(PathBuf::from("missing.json"));
        for path in ["mcp", "/mcp?query", "/mcp#fragment"] {
            options.path = path.to_owned();
            assert!(serve_http(options.clone()).await.is_err(), "{path}");
        }
        options.path = "/mcp".to_owned();
        options.host = "not a valid host".to_owned();
        assert!(serve_http(options).await.is_err());
    }

    #[test]
    fn router_configuration_covers_wildcard_stateless_and_empty_credentials() {
        let mut options = HttpOptions::new(PathBuf::from("missing.json"));
        options.host.clear();
        options.api_key = Some(String::new());
        options.stateless = true;
        options.json_response = true;
        options.session_timeout = Some(Duration::ZERO);
        let cancellation = CancellationToken::new();
        assert!(build_http_router(&options, &cancellation).is_ok());
    }

    #[tokio::test]
    async fn legacy_session_transport_enforces_auth_and_lists_tools()
    -> Result<(), Box<dyn std::error::Error>> {
        let temp = tempfile::tempdir()?;
        let graph = temp.path().join("graph.json");
        fs::write(
            &graph,
            r#"{"directed":true,"nodes":[{"id":"a","label":"Alpha","community":0}],"links":[]}"#,
        )?;
        let mut options = HttpOptions::new(graph);
        options.api_key = Some("s3cret".to_owned());
        options.json_response = true;
        let cancellation = CancellationToken::new();
        let router = build_http_router(&options, &cancellation)?;
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await?;
        let address = listener.local_addr()?;
        let server_cancel = cancellation.clone();
        let server = tokio::spawn(async move {
            axum::serve(listener, router)
                .with_graceful_shutdown(server_cancel.cancelled_owned())
                .await
        });

        let unauthorized = request(address, "127.0.0.1", None, None, INITIALIZE).await?;
        assert!(unauthorized.starts_with("HTTP/1.1 401 Unauthorized"));
        assert!(unauthorized.ends_with("{\"error\": \"unauthorized\"}"));

        let initialized = request(
            address,
            "127.0.0.1",
            Some("Bearer s3cret"),
            None,
            INITIALIZE,
        )
        .await?;
        assert!(initialized.starts_with("HTTP/1.1 200 OK"));
        // rmcp frames both initialization and subsequent legacy-session responses as SSE,
        // even when the stateless transport's JSON response preference is enabled.
        assert!(
            initialized
                .to_lowercase()
                .contains("content-type: text/event-stream")
        );
        let session = header_value(&initialized, "mcp-session-id").ok_or("missing session id")?;
        let payload: Value = sse_data_json(response_body(&initialized))?;
        assert_eq!(payload["result"]["serverInfo"]["name"], "compass");

        let listed = request(
            address,
            "127.0.0.1",
            Some("bearer s3cret"),
            Some(&session),
            r#"{"jsonrpc":"2.0","id":2,"method":"tools/list","params":{}}"#,
        )
        .await?;
        assert!(listed.starts_with("HTTP/1.1 200 OK"));
        assert!(
            listed
                .to_lowercase()
                .contains("content-type: text/event-stream")
        );
        let payload: Value = sse_data_json(response_body(&listed))?;
        assert_eq!(
            payload["result"]["tools"].as_array().map(Vec::len),
            Some(18)
        );

        cancellation.cancel();
        server.await??;
        Ok(())
    }

    #[tokio::test]
    async fn http_gate_requires_write_capability_only_for_agent_mutation()
    -> Result<(), Box<dyn std::error::Error>> {
        let temp = tempfile::tempdir()?;
        let project = temp.path().canonicalize()?;
        let mut options = HttpOptions::new(project.join("missing.json"));
        options.api_key = Some("read-secret".to_owned());
        options.write_api_key = Some("write-secret".to_owned());
        options.json_response = true;
        options.agent_graph = Some(crate::AgentGraphMcpConfig {
            writes_enabled: true,
            masks_enabled: false,
            principal: compass_agent_graph::PrincipalId::parse("principal:http-gate")?,
            allowed_projects: std::collections::BTreeSet::from([project.clone()]),
            non_git_state_root: Some(project.join("agent-state")),
        });
        let cancellation = CancellationToken::new();
        let router = build_http_router(&options, &cancellation)?;
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await?;
        let address = listener.local_addr()?;
        let server_cancel = cancellation.clone();
        let server = tokio::spawn(async move {
            axum::serve(listener, router)
                .with_graceful_shutdown(server_cancel.cancelled_owned())
                .await
        });
        let initialized = request(
            address,
            "127.0.0.1",
            Some("Bearer read-secret"),
            None,
            INITIALIZE,
        )
        .await?;
        let session = header_value(&initialized, "mcp-session-id").ok_or("missing session id")?;
        let write = r#"{"jsonrpc":"2.0","id":2,"method":"tools/call","params":{"name":"apply_agent_graph","arguments":{}}}"#;
        let denied = request(
            address,
            "127.0.0.1",
            Some("Bearer read-secret"),
            Some(&session),
            write,
        )
        .await?;
        assert!(denied.starts_with("HTTP/1.1 403 Forbidden"));
        assert!(denied.ends_with("{\"error\": \"write_capability_required\"}"));

        let admitted = request_with_write_key(
            address,
            "127.0.0.1",
            Some("Bearer read-secret"),
            Some("write-secret"),
            Some(&session),
            write,
        )
        .await?;
        assert!(!admitted.starts_with("HTTP/1.1 403 Forbidden"));
        cancellation.cancel();
        server.await??;
        Ok(())
    }

    #[tokio::test]
    async fn local_http_transport_rejects_untrusted_host() -> Result<(), Box<dyn std::error::Error>>
    {
        let temp = tempfile::tempdir()?;
        let graph = temp.path().join("graph.json");
        fs::write(&graph, r#"{"directed":true,"nodes":[],"links":[]}"#)?;
        let mut options = HttpOptions::new(graph);
        options.json_response = true;
        options.stateless = true;
        let cancellation = CancellationToken::new();
        let router = build_http_router(&options, &cancellation)?;
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await?;
        let address = listener.local_addr()?;
        let server_cancel = cancellation.clone();
        let server = tokio::spawn(async move {
            axum::serve(listener, router)
                .with_graceful_shutdown(server_cancel.cancelled_owned())
                .await
        });
        let response = request(address, "attacker.example", None, None, INITIALIZE).await?;
        assert!(response.starts_with("HTTP/1.1 403 Forbidden"));
        cancellation.cancel();
        server.await??;
        Ok(())
    }

    async fn request(
        address: SocketAddr,
        host: &str,
        authorization: Option<&str>,
        session: Option<&str>,
        body: &str,
    ) -> Result<String, Box<dyn std::error::Error>> {
        request_with_write_key(address, host, authorization, None, session, body).await
    }

    async fn request_with_write_key(
        address: SocketAddr,
        host: &str,
        authorization: Option<&str>,
        write_key: Option<&str>,
        session: Option<&str>,
        body: &str,
    ) -> Result<String, Box<dyn std::error::Error>> {
        let mut stream = tokio::net::TcpStream::connect(address).await?;
        let authorization = authorization
            .map(|value| format!("Authorization: {value}\r\n"))
            .unwrap_or_default();
        let write_key = write_key
            .map(|value| format!("x-compass-write-key: {value}\r\n"))
            .unwrap_or_default();
        let session = session
            .map(|value| format!("Mcp-Session-Id: {value}\r\n"))
            .unwrap_or_default();
        let wire = format!(
            "POST /mcp HTTP/1.1\r\nHost: {host}\r\nContent-Type: application/json\r\nAccept: application/json, text/event-stream\r\n{authorization}{write_key}{session}Content-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        );
        stream.write_all(wire.as_bytes()).await?;
        let mut response = Vec::new();
        stream.read_to_end(&mut response).await?;
        Ok(String::from_utf8(response)?)
    }

    fn response_body(response: &str) -> &str {
        response.split_once("\r\n\r\n").map_or("", |(_, body)| body)
    }

    /// Parse the JSON response after any empty SSE priming events (SEP-1699).
    fn sse_data_json(body: &str) -> Result<Value, Box<dyn std::error::Error>> {
        let data = body
            .lines()
            .filter_map(|line| line.strip_prefix("data:"))
            .map(str::trim)
            .find(|data| !data.is_empty())
            .ok_or("no nonempty SSE data line in response body")?;
        Ok(serde_json::from_str(data)?)
    }

    fn header_value(response: &str, name: &str) -> Option<String> {
        response
            .lines()
            .filter_map(|line| line.split_once(':'))
            .find(|(candidate, _)| candidate.eq_ignore_ascii_case(name))
            .map(|(_, value)| value.trim().to_owned())
    }
}

